const inputData = $('Disparador de Sub-Workflow').first()?.json || {};
const mantisResp = $input.first()?.json || {};
const ticketId = mantisResp.issue?.id || mantisResp.id || ('INC-' + Math.floor(1000 + Math.random() * 9000));

const alertName = inputData.alertName || 'PostgresNodeDown';
const node = inputData.node || inputData.instance || 'nodo-desconocido';
const severity = inputData.severity || 'critical';
const summary = inputData.summary || 'Caída de nodo de clúster';
const description = inputData.description || 'El nodo no responde a healthchecks';
const startsAt = inputData.startsAt || new Date().toISOString();

const promptAnalisis = `Se ha producido una alerta crítica en la infraestructura de ExpoJuy 2026:\n` +
  `• Alerta: ${alertName}\n` +
  `• Nodo/Instancia afectada: ${node}\n` +
  `• Severidad: ${severity}\n` +
  `• Resumen: ${summary}\n` +
  `• Descripción de Prometheus: ${description}\n` +
  `• Ticket Mantis asociado: #${ticketId}\n` +
  `• Fecha/Hora de detección: ${startsAt}\n\n` +
  `Consulta la herramienta de conocimiento "runbooks_infraestructura_expojuy" para recuperar los procedimientos oficiales de recuperación de PostgreSQL HA en Docker y redacta un INFORME TÉCNICO Y RUNBOOK DE REMEDIACIÓN estructurado en Markdown:\n` +
  `1. Diagnóstico de Causa Raíz y Radio de Impacto\n` +
  `2. Procedimiento de Remediación Paso a Paso con comandos docker compose y psql precisos\n` +
  `3. Verificación Post-Recuperación de la Replicación y Balanceador HAProxy\n` +
  `4. Medidas Preventivas para evitar recurrencia.`;

return [{
  json: {
    ...inputData,
    ticketId,
    alertName,
    node,
    severity,
    summary,
    description,
    promptAnalisis
  }
}];

const prev = $('Preparar Prompt de Diagnóstico').first().json;
const agentOutput = $input.first().json.output || $input.first().json.text || 'Diagnóstico generado automáticamente por el sistema RAG.';

const fileName = `RUNBOOK_INCIDENTE_${prev.ticketId}_${prev.alertName}.md`;

const docHeader = `# INFORME DE INCIDENTE Y RUNBOOK DE OPERACIÓN - EXPOJUY 2026\n\n` +
  `**Ticket Mantis:** #${prev.ticketId}  \n` +
  `**Alerta:** \`${prev.alertName}\`  \n` +
  `**Nodo/Instancia:** \`${prev.node}\`  \n` +
  `**Severidad:** \`${prev.severity.toUpperCase()}\`  \n` +
  `**Fecha de Detección:** ${prev.startsAt}  \n` +
  `**Generado por:** Asistente RAG SRE (n8n & Google Gemini)  \n\n` +
  `---\n\n`;

const fullMarkdown = docHeader + agentOutput;

// Resumen sintético para enviar por Telegram
const telegramAlert = `🚨 *INCIDENCIA CRÍTICA EN CLÚSTER DE BD* 🚨\n\n` +
  `• *Alerta:* \`${prev.alertName}\`\n` +
  `• *Nodo afectado:* \`${prev.node}\`\n` +
  `• *Ticket Mantis:* #${prev.ticketId}\n` +
  `• *Diagnóstico RAG:* ${prev.summary}\n` +
  `• *Documentación:* Se subió runbook \`${fileName}\` a Nextcloud.\n\n` +
  `_Revisar la carpeta de Documentos en Nextcloud para ejecutar los pasos de remediación._`;

return [{
  json: {
    ...prev,
    fileName,
    fullMarkdown,
    telegramAlert
  }
}];
